def CancellaPrima(p, x):
    if p is None:
        return None
    if p.key == x:
        # il nodo p va eliminato: il resto della lista non si tocca
        return p.next
    p.next = CancellaPrima(p.next, x)
    return p

# uso: lista = CancellaPrima(lista, x)
# tempo O(n), spazio O(n) per lo stack

def CancellaTutte(p, x):
    if p is None:
        return None
    if p.key == x:
        # p va eliminato: la nuova testa è il resto già ripulito
        return CancellaTutte(p.next, x)
    p.next = CancellaTutte(p.next, x)
    return p

# uso: lista = CancellaTutte(lista, x)
# tempo Θ(n), spazio O(n) per lo stack

def CancellaUltimo(p):
    if p is None:
        return None
    if p.next is None:
        # p è l'ultimo nodo: sparisce
        return None
    p.next = CancellaUltimo(p.next)
    return p

# uso: lista = CancellaUltimo(lista)
# tempo Θ(n), spazio O(n) per lo stack

def InserisciR(p, x):
    if p is None or p.key < x:
        # lista vuota o x va prima di p (ordine decrescente): il nuovo nodo punta a p
        return Nodo(x, p)
    if p.key == x:
        # già presente: nessuna modifica
        return p
    p.next = InserisciR(p.next, x)
    return p

# uso: lista = InserisciR(lista, x)
# tempo O(n), spazio O(n) per lo stack

def InserisciR(p, x):
    if p is None or p.key >= x:
        # lista vuota o x non è maggiore di p: il nuovo nodo va prima di p
        return Nodo(x, p)
    p.next = InserisciR(p.next, x)
    return p

# uso: lista = InserisciR(lista, x)
# tempo O(n), spazio O(n) per lo stack

def InserisciR(p, x):
    if p is None or p.key > x:
        # x va prima di p (o in fondo): nodo nuovo, inserimento avvenuto
        return (Nodo(x, p), True)
    if p.key == x:
        # già presente: lista invariata
        return (p, False)
    resto, inserito = InserisciR(p.next, x)
    p.next = resto
    return (p, inserito)

# uso: lista, ok = InserisciR(lista, x)
# tempo O(n), spazio O(n) per lo stack

def Somma(p):
    if p is None:
        return 0
    return p.key + Somma(p.next)

# tempo Θ(n), spazio O(n) per lo stack

def Massimo(p):
    if p is None:
        return None          # la lista vuota non ha massimo
    if p.next is None:
        return p.key         # un solo nodo: è il massimo
    m = Massimo(p.next)
    return max(p.key, m)

# tempo Θ(n), spazio O(n) per lo stack

def Cali(p):
    if p is None or p.next is None:
        return 0             # con meno di due nodi non ci sono coppie
    if p.key > p.next.key:
        return 1 + Cali(p.next)
    return Cali(p.next)

# tempo Θ(n), spazio O(n) per lo stack

def Posizione(p, x):
    if p is None:
        return -1            # x assente
    if p.key == x:
        return 0             # x è nel nodo corrente
    r = Posizione(p.next, x)
    if r == -1:
        return -1            # assente anche nel resto: non si somma 1
    return r + 1

# tempo O(n), spazio O(n) per lo stack

def TuttePari(p):
    if p is None:
        return True          # nessun nodo viola la proprietà
    if p.key % 2 != 0:
        return False         # un nodo dispari: risposta nota
    return TuttePari(p.next)

# tempo O(n), spazio O(n) per lo stack

def DueUguali(p):
    if p is None or p.next is None:
        return False         # servono almeno due nodi
    if p.key == p.next.key:
        return True          # coppia trovata
    return DueUguali(p.next)

# tempo O(n), spazio O(n) per lo stack

def CopiaMaggiori(p, x):
    if p is None:
        return None
    if p.key > x:
        # nodo nuovo: non si riusa p
        return Nodo(p.key, CopiaMaggiori(p.next, x))
    return CopiaMaggiori(p.next, x)

# uso: nuova = CopiaMaggiori(lista, x); la lista di partenza non cambia
# tempo Θ(n), spazio O(n) per lo stack (più i nodi creati)

def InserisciInCoda(p, x):
    if p is None:
        return Nodo(x, None)
    p.next = InserisciInCoda(p.next, x)
    return p

# uso: lista = InserisciInCoda(lista, x)
# tempo Θ(n), spazio O(n) per lo stack

def Fondi(p, q):
    if p is None:
        return q
    if q is None:
        return p
    if p.key <= q.key:
        p.next = Fondi(p.next, q)
        return p
    q.next = Fondi(p, q.next)
    return q

# uso: lista = Fondi(p, q); nessun nodo nuovo
# tempo O(n + m) (Θ(n + m) nel caso peggiore), spazio O(n + m) per lo stack
